return [{ chat_id: $json.chat_id, text, reply_markup }];

const arg = ($json.arg || '').trim();
const cleaned = arg.replace(/^\[|\]$/g, '').trim();
const id = Number(cleaned);
return [{ ...$json, row_id_arg: Number.isFinite(id) ? id : '' }];

const items = $input.all().map(i => i.json);
let rows = items;
if (items.length === 1 && Array.isArray(items[0].data)) rows = items[0].data;
const draft = rows?.[0];
return [{ ...$json, draft_text: (draft?.draft_text ?? '').toString().trim() }];
